'use strict';
var fs=require('fs'),path=require('path'),child=require('child_process'),UserDataService=require('./user_data_service'),bridge=require('./legacy_bridge');
var root=path.resolve(__dirname,'..'),userFile=path.join(__dirname,'local_username.dat');
function resolveUsername(){var env=String(process.env.IATB_USERNAME||'').trim();if(env)return env;try{var saved=String(fs.readFileSync(userFile,'utf8')||'').trim();if(saved)return saved;}catch(e){}try{var legacy=JSON.parse(fs.readFileSync(path.join(root,'user.dat'),'utf8'));var base=String(legacy.username||legacy.displayName||legacy.email||'').trim();if(base)return base.indexOf('@')>0?base.split('@')[0]:base;}catch(e){}return'default';}
function serverReady(){try{child.execFileSync('/usr/bin/curl',['-sS','-f','--connect-timeout','1','--max-time','2','http://127.0.0.1:'+(process.env.IATB_USERDATA_SERVER_PORT||'8020')+'/health'],{stdio:'ignore'});return true;}catch(e){return false;}}
function ensureLocalServer(){if(String(process.env.IATB_USERDATA_REMOTE_MODE||'HTTP').toUpperCase()==='FILESYSTEM')return;if(serverReady())return;try{var p=child.spawn(process.execPath,[path.join(__dirname,'local_server.js')],{cwd:root,detached:true,stdio:'ignore',env:Object.assign({},process.env)});p.unref();}catch(e){throw new Error('USERDATA_SERVER_START_FAILED: '+e.message);}for(var i=0;i<10&&!serverReady();i++)try{child.execFileSync('/bin/sleep',['0.15']);}catch(e){}if(!serverReady())throw new Error('USERDATA_SERVER_UNAVAILABLE');}
function startAgent(){try{var p=child.spawn(process.execPath,[path.join(__dirname,'sync_agent.js')],{cwd:root,detached:true,stdio:'ignore',env:Object.assign({},process.env)});p.unref();}catch(e){console.error('[UserData] sync agent start failed:',e.message);}}
ensureLocalServer();
var svc=new UserDataService(root,{username:resolveUsername()});
try{var s=svc.bootstrap();bridge.restoreOrImport(svc);s=svc.status();try{fs.writeFileSync(userFile,s.username+'\n','utf8');}catch(e){}svc.syncRemote();console.log('[UserData] READY user='+s.username+' db='+s.dbPath+' remote='+s.remotePath);svc.close(false);startAgent();process.exit(0);}catch(e){console.error('[UserData] BOOTSTRAP ERROR:',e&&e.message||e);try{svc.close(false);}catch(x){}process.exit(1);}
